package com.zoro.zoromart.util;
import java.math.BigDecimal;import java.util.regex.Pattern;
/** Common server-side input validation. */
public final class ValidationUtil {private static final Pattern EMAIL=Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");private ValidationUtil(){} public static String required(String v,String field){if(v==null||v.trim().isEmpty())throw new IllegalArgumentException(field+" is required");return v.trim();}public static String email(String v){v=required(v,"email").toLowerCase();if(!EMAIL.matcher(v).matches()||v.length()>190)throw new IllegalArgumentException("Valid email is required");return v;}public static int quantity(int q){if(q<1||q>999)throw new IllegalArgumentException("Quantity must be between 1 and 999");return q;}public static BigDecimal price(String s){try{BigDecimal b=new BigDecimal(s);if(b.signum()<0||b.scale()>2||b.precision()>10)throw new IllegalArgumentException("Price must be a valid amount with up to 2 decimals");return b;}catch(NumberFormatException e){throw new IllegalArgumentException("Valid price is required");}}}
